import json
from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import GordonURI


class GordonV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def reset_node_bmc(self, node_id, upgrade_type, timeout=60):
        body = {
            "node_id": node_id,
            "upgrades": [{
                "upgrade": upgrade_type,
                "bmc_cleanup": False,
                "preserve_credentials": False
            }]
        }
        uri = GordonURI().gordon_upgrade_uri
        bmc_rest_res = self.api_client.send_post_request(uri=uri,
                                                         data=json.dumps(body),
                                                         headers={"Content-Type": "application/json"},
                                                         timeout=timeout)
        return bmc_rest_res['Location'].rsplit('/', 1)[1]

    def get_upgrade_state(self, task_id, timeout=60):
        uri = GordonURI().gordon_status_uri + "/" + task_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def start_upgrade(self, node_id, upgrades, timeout=60):
        data = {
            "node_id": node_id,
            "upgrades": upgrades
            }
        uri = GordonURI().gordon_upgrade_uri
        result = self.api_client.send_post_request(uri=uri,
                                                   data=json.dumps(data),
                                                   headers={"Content-Type": "application/json"},
                                                   timeout=timeout)
        return result['Location']

    def upgrade_esw_firmware(self, node_id, component_type, file_id, upgrade_type, reset_payload=False, timeout=60):
        steps = {'hpe_upgrade': [
                                    {"description": "Checking server credentials"},
                                    {"description": "Determining the suitable upgrade method"},
                                    {"description": "Verifying server state"},
                                    {"description": "Checking iLO task queue"},
                                    {"description": "Preparing for the upgrade"},
                                    {"description": "Starting the upgrade"},
                                    {"description": "Checking the upgrade status"},
                                    {"description": "Finalizing the upgrade"}
                                ],
                 'dell_upgrade': [
                                   {"description": "Checking server credentials"},
                                   {"description": "Determining the suitable upgrade method"},
                                   {"description": "Setting upgrade apply time"},
                                   {"description": "Preparing for the upgrade"},
                                   {"description": "Starting the upgrade"},
                                   {"description": "Checking the upgrade status"},
                                   {"description": "Finalizing the upgrade"}
                                 ]
                }
        upgrades = [
                      {
                        "access": "redfish",
                        "cleanup_steps": [
                                           {"description": "Re-reading node details"},
                                           {"description": "Checking node inspection status"}
                                         ],
                        "component": component_type,
                        "description": "Upgrades the firmware",
                        "file": file_id,
                        "options": {"preserve_config_by_default": True},
                        "priority": 1,
                        "reset_payload": reset_payload,
                        "steps": [],
                        "upgrade": upgrade_type,
                        "upgrade_type": "obm"
                      }
                    ]

        upgrades[0]['steps'] = steps[upgrade_type]
        return self.start_upgrade(node_id, upgrades, timeout=timeout)

    def execute_remote_image(self, node_id, file_id, timeout=60):
        upgrades = [
                      {
                         "upgrade": "run_remote_image",
                         "file": file_id
                      }
                   ]

        return self.start_upgrade(node_id, upgrades, timeout=timeout)

    def reset_rannic_card(self, node_id, rannic_location="1", reset_type="warm", timeout=60):
        upgrades = [
                        {
                            "location": rannic_location,
                            "reset_type": reset_type,
                            "upgrade": "rannic_accelerator_reset"
                        }
                   ]
        return self.start_upgrade(node_id, upgrades, timeout=timeout)
